def solve(board, word):
    if not word:
        return True
    if not board or not board[0]:
        return False
    rows, columns = len(board), len(board[0])
    if len(word) > rows * columns:
        return False
    used = set()
    def visit(row, column, index):
        if not (0 <= row < rows and 0 <= column < columns):
            return False
        if (row, column) in used or board[row][column] != word[index]:
            return False
        if index == len(word) - 1:
            return True
        used.add((row, column))
        found = any(visit(row + dr, column + dc, index + 1)
                    for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)))
        used.remove((row, column))
        return found
    return any(visit(row, column, 0)
               for row in range(rows) for column in range(columns))

